  result[2,2] = 0L
  result[3,3] = 0L
  return result
}

fun num_paths(n : Int) : Long {
  fun raise_to(t : TransitionMatrix, x : Int) : TransitionMatrix {
    if (x == 0) {
      val result = identity_matrix()
      return result
    } else if ((x % 2) == 0) {
      val t_sqr = t * t
      val x_div_2 = x / 2
      val result = raise_to(t_sqr, x_div_2)
      return result
    } else {
      val t_sqr = t * t
      val x_minus_1_div_2 = (x - 1) / 2
      val result = t * raise_to(t_sqr, x_minus_1_div_2)
      return result
    }
  }
  val t_matrix = ant_matrix()
  val result = raise_to(t_matrix, n)
  return result[0,0]
}

fun main(args : Array<String>) {
  val n_nullable_str = readLine()
  if (n_nullable_str == null) {
    // Do nothing ...
  } else {
    val n_str = n_nullable_str
    val n = n_str.toInt()
    val result = num_paths(n)
    println("${result}")
  }
}
